      "呜呼圣王及圣相，相与烜赫流淳熙。",
      "公之斯文不示后，曷与三五相攀追。",
      "愿书万本诵万遍，口角流沫右手胝。",
      "传之七十有二代，以为封禅玉检明堂基。"
