      "霍如羿射九日落，矫如群帝骖龙翔。",
      "来如雷霆收震怒，罢如江海凝清光。",
      "绛唇珠袖两寂寞，晚有弟子传芬芳。",
      "临颍美人在白帝，妙舞此曲神扬扬。",
      "与余问答既有以，感时抚事增惋伤。",
      "先帝侍女八千人，公孙剑器初第一。",
      "五十年间似反掌，风尘澒洞昏王室。",
      "梨园弟子散如烟，女乐余姿映寒日。",
      "金粟堆南木已拱，瞿唐石城草萧瑟。",
      "玳筵急管曲复终，乐极哀来月东出。",
      "老夫不知其所往，足茧荒山转愁疾。"
